-- Выпуск 15 в журнале обновлений (ADR 0077): линейная техника — заказ на объект ведётся днями.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0102, 0109, 0113, 0116, 0125
-- и 0126 (ADR 0077 §4).
--
-- Хвост версии — `0100`: весь блок принят одним решением, ADR 0100. Номер миграции 0128, а не 0127
-- и не 0129: 0127 занят схемой самой линейной техники (та же тема, но это схема, а не запись
-- журнала), 0129 — параллельной работой по коррекции листов задним числом. Разрыв в нумерации
-- дешевле столкновения — тот же размен, что в 0113, 0125 и 0126.
--
-- Одним выпуском, а не тремя: признак типа, ЭСМ-2 по требованию и дни в рейсах — стороны одного
-- утверждения «эта машина вечером возвращается на базу». Порознь они читались бы как отключённая
-- бумага, новая галочка в справочнике и непонятно откуда взявшаяся таблица дней.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  15, '0.1.15.0100', '2026-08-12', 'Линейная техника: 4-П на каждый день, ЭСМ-2 по требованию', '{100}',
  '[
    {"kind":"feature","text":"У типа техники появился признак «Линейная техника» — для машин, которые вечером возвращаются на базу и за день работают на нескольких объектах: автовышка, каток, поливомоечная. Заказы такой техники портал ведёт по дням"},
    {"kind":"feature","text":"У заказа линейной техники появилась вкладка «Дни работ»: на каждый день срока видно, какая машина и какой водитель выходят на объект, выписан ли путевой лист и сколько часов подтвердила площадка"},
    {"kind":"feature","text":"День заказа ставится в рейс из карточки заявки — по одному дню: в разные дни выходят разные машины и разные водители, и портал не подставляет вчерашних. Если у машины на этот день уже есть рейс, день встаёт его строкой задания, а не заводит второй лист"},
    {"kind":"feature","text":"Работа линейной машины на объекте печатается в 4-П рейса: в задании стоят наименование и адрес площадки, а в графе груза — характер работ из заявки. Талон заказчика у такого дня свой, как у перевозки"},
    {"kind":"feature","text":"Недельные листы ЭСМ-2 по линейному заказу портал больше не выписывает сам — их выписывают из карточки заявки, по неделе за раз, выбирая машину и машиниста. Неделю на объекте могут закрыть две разные единицы, и у каждой будет свой лист со своими моточасами"},
    {"kind":"improvement","text":"Линейная машина больше не числится занятой весь срок заказа: в гараже она занята теми днями, на которые её поставили в рейс, — остальные дни свободны для других объектов"},
    {"kind":"improvement","text":"В срезе «На объекте» у линейного заказа показывается машина этого дня, а не та, которой заказ взяли в работу; нераспланированный день так и подписан — «на этот день машина не назначена»"},
    {"kind":"improvement","text":"Поиск заявок по машине находит и те заказы, где эта единица отработала отдельные дни, и называет, какие именно: раньше отбор знал только машину, назначенную на заявку целиком"},
    {"kind":"improvement","text":"Сводка «Техника на объектах» в письмах больше не теряет линейные заказы: в неё попадают дни окна с номерами их путевых листов, а где лист ещё не выписан — номер рейса с пометкой, чтобы это было видно до выезда"},
    {"kind":"improvement","text":"Перенос рейса на другую дату переносит и день заказа, который в нём стоит, а увести день за срок заявки или в день, где у неё уже есть рейс, портал не даёт — объясняя, что именно мешает"},
    {"kind":"improvement","text":"Перевод линейного заказа в работу больше не требует машиниста и не предлагает доставку техники на объект: листы в этот момент не выписываются, а перегона у такой машины нет — она уезжает на объект своим ходом каждый день"},
    {"kind":"improvement","text":"Признак линейной техники нельзя переключить у типа, по которому уже работают заявки: иначе заказ сменил бы порядок работы с документами на ходу. Портал называет число таких заявок"}
  ]'::jsonb
);
